pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;

    // Normalize job demands
    let job_cpu_norm = job_cpu as f64 / node_capacity_cpu as f64;
    let job_ram_norm = job_ram as f64 / node_capacity_ram as f64;

    // Dominant bottleneck heuristic
    let dominant_bottleneck = if cpu_norm < ram_norm { cpu_norm } else { ram_norm };

    // Cross-product alignment
    let cross_product = (cpu_norm * job_cpu_norm) + (ram_norm * job_ram_norm);

    // Penalize resource imbalance
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    // Dynamic horizon awareness
    let dynamic_horizon = step_index as f64 / total_jobs as f64;

    // Lookahead awareness (k=2)
    let next_job_norm_cpu = next_job_cpu as f64 / node_capacity_cpu as f64;
    let next_job_norm_ram = next_job_ram as f64 / node_capacity_ram as f64;
    let lookahead_score = if node_residual_cpu >= next_job_cpu && node_residual_ram >= next_job_ram {
        1.0 - (imbalance_penalty + dynamic_horizon) * 0.5
    } else {
        imbalance_penalty + dynamic_horizon
    };

    // Non-linear conditionals for compaction and balance
    let compaction_bonus = if node_residual_cpu < mean_cpu_residual || node_residual_ram < mean_ram_residual { -1.0 } else { 1.0 };
    let cpu_balance_bonus = if (cpu_norm - 0.5).abs() < (ram_norm - 0.5).abs() { 1.0 } else { -1.0 };

    // Combine lookahead packing bonuses
    let lookahead_packing_bonus = if node_residual_cpu >= next_job_cpu && node_residual_ram >= next_job_ram {
        2.0 - (imbalance_penalty + dynamic_horizon) * 0.5
    } else {
        imbalance_penalty + dynamic_horizon
    };

    // Fine-tuned weights and terms to improve compaction and balance
    let score = dominant_bottleneck * cross_product * compaction_bonus * cpu_balance_bonus 
        - imbalance_penalty * dynamic_horizon * lookahead_score 
        + lookahead_packing_bonus * 1.2;
    score
}

